examples.template:
LazyVGrid(
    columns: [GridItem(.adaptive(minimum: {{minItemWidth}} * 16), spacing: theme.spacing.space4)],
    spacing: theme.spacing.space4
) {
    ForEach(projects, id: \.self) { project in
        MonarchCard {
            VStack(alignment: .leading, spacing: 4) {
                Text(project).monarchTextStyle(.subheading)
                Text({{description}}).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
            }
            Text({{body}}).monarchTextStyle(.body)
        }
    }
}

